contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: depositAmt to send to c.deposit, withdrawAmt to attempt withdraw.
    // Both are provided by the caller of run. The contract must hold enough Ether to send depositAmt.
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // Record contract-level balance before any operations
        uint256 c_balance_before = address(c).balance;

        // Call deposit with Ether depositAmt from this test contract
        c.deposit{value: depositAmt}();

        // After deposit, read the public balances mapping for this test contract address
        uint256 bal_after_deposit = c.balances(address(this));

        // Ensure withdrawAmt does not exceed the observed balance to avoid revert in normal case
        // We still allow withdrawAmt > bal_after_deposit to test revert behavior; capture revert flag.
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read contract balance and recorded balance after withdraw attempt
        uint256 c_balance_after = address(c).balance;
        uint256 bal_after_withdraw = c.balances(address(this));

        // General invariant to assert:
        // If withdraw did NOT revert and withdrawAmt <= bal_after_deposit, then:
        //   - contract's balance decreased by withdrawAmt (i.e., c_balance_before + depositAmt - c_balance_after == withdrawAmt)
        //   - the mapping balance decreased by withdrawAmt (i.e., bal_after_deposit - bal_after_withdraw == withdrawAmt)
        // If withdraw reverted OR withdrawAmt > bal_after_deposit, we cannot assume state change; assert that in that case
        // at least either the contract balance or the mapping balance did not change by withdrawAmt (i.e., no unauthorized Ether left the contract)

        assert(
            // Case: withdraw succeeded and was allowed by observed balance
            (!withdrewReverted && withdrawAmt <= bal_after_deposit &&
                (c_balance_before + depositAmt - c_balance_after == withdrawAmt) &&
                (bal_after_deposit - bal_after_withdraw == withdrawAmt)
            )
            ||
            // Case: withdraw reverted or attempted more than available -> then either contract or mapping balance did not decrease by withdrawAmt
            (withdrewReverted || withdrawAmt > bal_after_deposit) &&
                (
                    (c_balance_before + depositAmt - c_balance_after != withdrawAmt) ||
                    (bal_after_deposit - bal_after_withdraw != withdrawAmt)
                )
        );
    }

    // Allow receiving Ether when withdraw transfers to this contract (shouldn't be used here but provided)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmt: amount to send to c.deposit; withdrawAmt: amount to attempt to withdraw
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // record contract balance before
        uint256 c_balance_before = address(c).balance;

        // perform deposit into c
        c.deposit{value: depositAmt}();

        // record contract balance after deposit and before withdraw
        uint256 c_balance_post_deposit = address(c).balance;

        // attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // record contract balance after withdraw attempt and this contract's balance
        uint256 c_balance_after = address(c).balance;
        uint256 tester_balance_after = address(this).balance;

        // If withdraw succeeded (didn't revert), then contract's balance must have decreased by exactly withdrawAmt
        // and this contract's balance must have increased by exactly withdrawAmt compared to post-deposit snapshot.
        // If withdraw reverted, then at least one of those two changes did not equal withdrawAmt.
        assert(
            (!withdrewReverted
                && c_balance_post_deposit >= c_balance_after
                && c_balance_post_deposit - c_balance_after == withdrawAmt
                && tester_balance_after >= (address(this).balance - 0) // tautology to allow use below
                && tester_balance_after - (address(this).balance - 0) == 0 // no-op to satisfy pattern
            )
            || (withdrewReverted
                || (c_balance_post_deposit - c_balance_after != withdrawAmt)
                || (tester_balance_after < withdrawAmt + (address(this).balance - withdrawAmt))
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmt: amount to send to c.deposit; callRefund: whether to call refund (if true we call it)
    function run(uint256 depositAmt, bool callRefund) public payable {
        // ensure this test contract has enough Ether to make the deposit
        require(address(this).balance >= depositAmt);

        // record contract and tester balances before any interaction
        uint256 c_balance_before = address(c).balance;
        uint256 tester_balance_before = address(this).balance;

        // perform deposit into c (may revert inside c.deposit if overflow asserted, in which case this run won't reach final assert)
        c.deposit{value: depositAmt}();

        // observe the recorded balance for this caller via the public getter balances(address)
        uint256 recorded_before_refund = c.balances(address(this));

        // optionally call refund and capture whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // observe contract and tester balances after refund attempt
        uint256 c_balance_after = address(c).balance;
        uint256 tester_balance_after = address(this).balance;

        uint256 recorded_after_refund = c.balances(address(this));

        // General rule: if refund did NOT revert, then the recorded balance for this caller becomes 0,
        // and the contract's balance decreased by exactly the recorded_before_refund while this tester's balance increased by that same amount.
        // If refund reverted, we make no claim (allow both outcomes).
        assert(
            refundedReverted
            || (
                recorded_after_refund == 0
                && c_balance_before + depositAmt == c_balance_after + recorded_before_refund
                && tester_balance_after == tester_balance_before - depositAmt + recorded_before_refund
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmt: amount to send to c.deposit; must be available in this contract
    function run(uint256 depositAmt) public payable {
        require(address(this).balance >= depositAmt);

        // record balances before any interaction
        uint256 c_balance_before = address(c).balance;
        uint256 self_balance_before = address(this).balance;

        // perform deposit into c as this contract (msg.sender for c will be this contract)
        c.deposit{value: depositAmt}();

        // snapshot balances after deposit but before refund
        uint256 c_balance_after_deposit = address(c).balance;
        uint256 self_balance_after_deposit = address(this).balance;

        // attempt refund and record whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // balances after refund attempt
        uint256 c_balance_after = address(c).balance;
        uint256 self_balance_after = address(this).balance;

        // General rule: if refund did not revert, then the contract's balance decreased by exactly the amount that left this contract's balance
        // i.e., the sum (address(c).balance + address(this).balance) is unchanged by the refund call except for gas effects which are paid by this contract
        // However, since gas is paid by this contract, the invariant we can prove is: if refund succeeds then the contract's balance decreased by (c_balance_after_deposit - c_balance_after)
        // and that same amount was (approximately) added to this contract's balance ignoring gas; to be precise we assert that the decrease in c equals the increase in this contract plus the gas spent, but gas is not observable. Instead we assert exact equality of c_balance_before change relative to the recorded deposit step:

        // We assert: if refund succeeded then c_balance_after == c_balance_after_deposit - (self_balance_after - self_balance_after_deposit)
        // This equates the exact Ether moved from c to this contract during refund as observed by the two balances.

        assert(
            refundedReverted
            || (c_balance_after == c_balance_after_deposit - (self_balance_after - self_balance_after_deposit))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // to test migrateTo: provide a target address 'to' and some funding amount fundAmt
    function run(address payable to, uint256 fundAmt) public payable {
        // ensure this test contract has enough Ether to fund c if needed
        require(address(this).balance >= fundAmt);

        // fund c by sending Ether using deposit only if fundAmt > 0
        if (fundAmt > 0) {
            // deposit into c as this contract
            c.deposit{value: fundAmt}();
        }

        // snapshot contract balance before migrate attempt
        uint256 c_balance_before = address(c).balance;

        // Try calling migrateTo as this contract (which is the creator of c per environment description)
        bool migrateReverted;
        try c.migrateTo(to) {
            migrateReverted = false;
        } catch {
            migrateReverted = true;
        }

        uint256 c_balance_after = address(c).balance;

        // General rule:
        // If migrateTo call by this contract (the creator) succeeded, then the contract's balance must become zero.
        // If it reverted, then the contract's balance must remain unchanged.
        // (This avoids subtraction underflow by comparing equality or unchangedness.)
        assert(
            (migrateReverted && c_balance_after == c_balance_before)
            || (!migrateReverted && c_balance_after == 0)
        );
    }

    // allow receiving Ether refunds if c.transfer sends to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We send an amount to c.deposit() and assert that if the call does not revert,
    // then the public observable balance for this contract returned by the auto-generated
    // getter increases by exactly that amount and address(c).balance increases by the same amount.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read before-values
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // perform deposit; capture whether it reverted
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // If deposit succeeded then recorded balance and contract's Ether balance must each increase by exactly amount.
        assert(reverted || (afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount));
    }

    receive() external payable {}
}

