contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first deposit some funds into c on behalf of this test contract, then attempt withdraw.
    // The rule: if withdraw succeeds (does not revert), then c's observable balance for this contract
    // decreases by exactly the withdrawn amount and this contract's Ether balance increases by exactly that amount.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // Ensure this test contract has enough ETH to perform the deposit call.
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint256 beforeContractEth = address(this).balance;
        uint256 beforeCbalance = address(c).balance;

        // Deposit into c on behalf of this contract. If this reverts the whole call will revert — that's allowed.
        c.deposit{value: depositAmount}();

        // After deposit, record on-chain observable values
        uint256 afterDeposit_C_bal = address(c).balance;
        // The public mapping balances is not declared public in C, so we must use behavior: C has no getter for balances.
        // However the problem statement allowed reading auto-generated getters; since balances is non-public we cannot read it.
        // Instead we can observe that withdrawing up to what we deposited should succeed and transfer Ether back.

        // Prepare to call withdraw and catch whether it reverts.
        // Ensure withdrawAmount is not larger than the total balance visible in c to avoid intrinsic revert in withdraw require.
        // We do not know the mapping entry, but withdraw will revert if withdrawAmount > balances[this]. To make the test meaningful,
        // choose withdrawAmount <= depositAmount so withdraw may succeed.
        require(withdrawAmount <= depositAmount);

        bool reverted;
        uint256 beforeThisEth = address(this).balance;
        uint256 beforeCbalForWithdraw = address(c).balance;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterThisEth = address(this).balance;
        uint256 afterCbalForWithdraw = address(c).balance;

        // General rule: if withdraw did not revert, then this contract's ETH balance increased by exactly withdrawAmount
        // and the contract's ETH balance decreased by exactly withdrawAmount.
        assert(reverted || (afterThisEth == beforeThisEth + withdrawAmount && afterCbalForWithdraw + withdrawAmount == beforeCbalForWithdraw));
    }

    // Allow receiving Ether when C.transfer is invoked
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first deposit some funds into c on behalf of this test contract, then call refund().
    // Rule: if refund() succeeds, address(this).balance increases by exactly the decrease in address(c).balance,
    // and address(c).balance becomes zero.
    function run(uint256 depositAmount) public payable {
        // Ensure this test contract has enough ETH to perform the deposit call.
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        // Deposit funds into C on behalf of this contract
        c.deposit{value: depositAmount}();

        // Record balances after deposit
        uint256 afterDepositThis = address(this).balance;
        uint256 afterDepositC = address(c).balance;

        // Now attempt refund(); capture whether it reverted
        bool refundedReverted;
        uint256 beforeRefundThis = address(this).balance;
        uint256 beforeRefundC = address(c).balance;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }
        uint256 afterRefundThis = address(this).balance;
        uint256 afterRefundC = address(c).balance;

        // If refund did not revert, then the decrease in C's balance equals the increase in this contract's balance,
        // and C's balance is now zero.
        assert(refundedReverted || (afterRefundThis == beforeRefundThis + (beforeRefundC - afterRefundC) && afterRefundC == 0));
    }

    // Allow receiving Ether when C.transfer is invoked
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first ensure c has enough Ether by having its creator migrate funds into it is not possible here,
    // so instead we rely on the fact that refund/deposit may revert; to avoid calling deposit (which can assert),
    // we only test the effect of withdraw when it is callable by this contract. The rule: if withdraw succeeds,
    // then address(c).balance decreases by at least amount and this contract's balance does not increase by more than amount.
    function run(uint256 amount) public payable {
        // No precondition on amount; ensure the test contract can receive any Ether sent by c via transfer.
        // Record balances before the withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool withdrewReverted;
        try c.withdraw(amount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If withdraw succeeded, then C's balance must have decreased by at least amount (it paid out up to amount)
        // and this contract's observable balance must not have increased by more than amount (transfer can't create Ether).
        // If withdraw reverted, we make no claim. Use non-underflow arithmetic by comparing with >= and <=.
        assert(withdrewReverted || (beforeC >= afterC && beforeC - afterC >= amount && afterThis <= beforeThis + amount));
    }

    // Accept Ether when C.transfer sends to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function; we take an amount to deposit first, then invoke refund and check properties
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // make an initial deposit into c from this contract
        c.deposit{value: depositAmount}();

        // read observable values before calling refund
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeCallerBalance = c.balances(address(this));

        bool didRevert;
        // call refund and catch revert if any
        try c.refund() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterContractBalance = address(c).balance;
        uint256 afterCallerBalance = c.balances(address(this));

        // General rule:
        // - If refund reverted, balances and contract balance remain unchanged (as observed).
        // - If refund succeeded, the caller's recorded balance becomes zero, and the contract balance decreased by exactly the previous recorded balance (i.e., no increase), and the contract balance did not increase.
        assert(
            (didRevert && afterContractBalance == beforeContractBalance && afterCallerBalance == beforeCallerBalance)
            ||
            (!didRevert && afterCallerBalance == 0 && afterContractBalance + beforeCallerBalance == beforeContractBalance && afterContractBalance <= beforeContractBalance)
        );
    }

    receive() external payable { }
}

