contract InvMutTest {
    C c;
    address payable creator;

    constructor(C _c) {
        c = _c;
        // The test harness deploys c with this contract as creator, so record it.
        creator = payable(address(this));
    }

    // We take an amount to fund the contract c (so it has nonzero balance), then attempt migrateTo.
    function run(uint256 fundAmount, address payable to) public payable {
        // ensure this contract has enough Ether to fund c
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund c so it holds some Ether. This uses the public payable deposit().
        // Avoid calling deposit if it might assert for overflow; instead send Ether directly to c by calling migrateTo only creator can call
        // But migrateTo sends whole balance out, so we need c to hold balance. Use deposit to credit this contract's balances in c.
        c.deposit{value: fundAmount}();

        // Record observable balances before migrateTo
        uint256 beforeC = address(c).balance;
        uint256 beforeTo = to.balance;

        bool didRevert;
        // Call migrateTo as creator (this contract is the creator). Capture revert status.
        try c.migrateTo(to) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterTo = to.balance;

        // If migrateTo reverted, c's balance must be unchanged. If it succeeded, c's balance becomes zero and the increase
        // in 'to' equals the decrease in c. Also ensure migrateTo cannot increase c's balance.
        assert(
            (didRevert && afterC == beforeC)
            ||
            (!didRevert && afterC == 0 && beforeC == afterTo - beforeTo && afterC <= beforeC)
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take an amount to fund c for this caller's balance, then call refund and assert the general rule.
    function run(uint256 fundAmount) public payable {
        // require the test contract has enough Ether to fund c if fundAmount > 0
        if (fundAmount > 0) require(address(this).balance >= fundAmount);

        // Deposit into c to set this caller's recorded balance. Avoid overflow by limiting fundAmount.
        // The deposit() in C asserts that balances[msg.sender] + msg.value > balances[msg.sender],
        // so disallow zero value deposits to avoid hitting that assert with msg.value == 0.
        if (fundAmount > 0) {
            c.deposit{value: fundAmount}();
        }

        // Observe c's ETH balance and this caller's recorded balance before refund
        uint256 beforeC = address(c).balance;
        uint256 beforeRecorded;
        // c.balances is not public in the original contract; attempt to read via autogenerated getter will fail if not public.
        // The problem statement shows `mapping(address => uint256) balances;` with no `public`, so we cannot read it.
        // Instead, observe only address(c).balance and address(this).balance changes. We still must express the rule
        // in terms of observable values: beforeC, beforeThis = address(this).balance
        uint256 beforeThis = address(this).balance;

        bool didRevert;
        try c.refund() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule (expressed using only observable values):
        // If refund reverted, contract balance unchanged and this contract balance unchanged.
        // If refund succeeded, then the decrease in c's balance equals the increase in this contract's balance,
        // and the decrease is <= beforeC (i.e., refund cannot increase c's balance and cannot create Ether).
        assert(
            (didRevert && afterC == beforeC && afterThis == beforeThis)
            ||
            (!didRevert && beforeC >= afterC && beforeThis <= afterThis && (beforeC - afterC) == (afterThis - beforeThis))
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

