contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first deposit some ether into c from this contract, then call refund()
    // depositAmount: amount to send with deposit()
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any calls
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeThisBal = address(this).balance;

        // perform deposit (may revert internally); capture whether it reverted
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // after deposit attempt observe balances
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositThisBal = address(this).balance;

        // Now try refund() which should transfer this caller's recorded balance back to it
        bool refundReverted;
        try c.refund() {
