        // General rule: withdraw either reverts leaving contract balance unchanged, or succeeds and
        // decreases contract balance by at least amount (can't create Ether). Additionally, when withdraw succeeds
        // it must not have increased the contract's balance (i.e., afterContractBal <= beforeContractBal).
        // This captures that withdraw cannot add Ether to the contract and that success consumes >= amount.
        assert(
            (reverted && afterContractBal == beforeContractBal)
            ||
            (!reverted && afterContractBal + amount <= beforeContractBal && afterContractBal <= beforeContractBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256 depositAmount) public payable {
        // ensure this contract has the Ether available to forward
        require(address(this).balance >= depositAmount || depositAmount == 0);

        // record observable before-values
        uint256 beforeContractBalance = address(c).balance;
        // balances mapping in C is not public, so we cannot read per-address balances directly.
        // But we can observe effects via address(c).balance and success of call.

        bool reverted;
        // call deposit forwarding depositAmount wei
        try c.deposit{value: depositAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: assert general invariant
        // If depositAmount == 0 then deposit may be allowed (no-op) or revert due to assert in C
        // For a positive depositAmount the contract's deposit() has an assert that should pass
        // and thus deposit should not revert; observable rule: if not reverted then contract balance increased by at least depositAmount
        // and if not reverted then depositAmount > 0 implies success. We assert a general rule combining these.
        assert(
            // If call reverted, we make no claim about balances (just allow revert)
            reverted
            || (
                // call succeeded
                // contract balance increased by >= depositAmount
                address(c).balance >= beforeContractBalance + depositAmount
            )
        );
    }

    // allow receiving ETH to fund forwarded deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking a destination address to pass to migrateTo
    function run(address to) public payable {
        // No precondition on 'to'
        // Record observable before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        bool reverted;
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule:
        // - If call reverted, we make no claim about balances.
        // - If call succeeded, contract's balance must become zero afterwards, and this contract's observable balance cannot increase by more than the previous contract balance (no Ether creation).
        assert(
            reverted || (
                address(c).balance == 0
                && address(this).balance <= beforeThisBalance + beforeContractBalance
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount <= address(this).balance);

        // read before values
        uint256 beforeContractBal = address(c).balance;
        // the mapping balances is not public in C, so we cannot read it directly; instead we will observe effects via withdraw/refund later.

        bool reverted;
        // perform deposit sending Ether
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;

        // If deposit reverted, contract balance must be unchanged. If it succeeded, contract balance increases exactly by amount.
        assert(reverted ? (afterContractBal == beforeContractBal) : (afterContractBal == beforeContractBal + amount));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt refund and assert conservation between contract and this test
    function run() public payable {
        // record observable balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeT = address(this).balance;

        bool reverted;
        // call refund on c and catch revert
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterT = address(this).balance;

        // If refund reverted, observable balances must be unchanged; otherwise the decrease of c's balance equals the increase of this test's balance.
        assert(reverted ? (afterC == beforeC && afterT == beforeT) : (beforeC - afterC == afterT - beforeT));
    }

    receive() external payable {}
}

